// NutriCoachTip.kt
// This data class defines the structure of a NutriCoach tip entity to be stored in the Room database.
// Each entry corresponds to a tip shown to the user, including the type, content, and timestamp.

package com.fit2081.fit2081assignment1.data

import androidx.room.Entity
import androidx.room.PrimaryKey

// This annotation marks the class as a Room entity and names the corresponding table "nutri_coach_tip".
@Entity(tableName = "nutri_coach_tip")
data class NutriCoachTip(
    // Primary key for the tip, auto-generated by Room.
    @PrimaryKey(autoGenerate = true) val id: Int = 0,

    // ID of the user the tip is associated with.
    val userId: String,

    // Indicates the type of tip source (e.g., "FruityVice" for fruit insights or "GenAI" for motivational messages).
    val tipType: String,

    // The actual message or tip content.
    val message: String,

    // Timestamp representing when the tip was generated or stored (usually in milliseconds).
    val timestamp: Long
)